// Rotate points counter-clockwise by degrees around origin
function rotate(points, degrees, origin = {x: 0, y: 0}) {
    // Validate input
    if (!Array.isArray(points)) {
        throw new Error("rotate: points must be an array");
    }

    if (typeof degrees !== 'number' || !isFinite(degrees)) {
        throw new Error("rotate: degrees must be a finite number");
    }

    if (!origin || typeof origin !== 'object' || origin.x === undefined || origin.y === undefined) {
        throw new Error("rotate: origin must be an object with x and y properties");
    }

    // Convert degrees to radians
    const radians = degrees * Math.PI / 180;
    const cos = Math.cos(radians);
    const sin = Math.sin(radians);

    // Create new points array to avoid mutating input
    const rotatedPoints = [];

    for (let i = 0; i < points.length; i++) {
        const point = points[i];

        // Validate point
        if (!point || typeof point !== 'object' || point.x === undefined || point.y === undefined) {
            throw new Error(`rotate: point at index ${i} must be an object with x and y properties`);
        }

        // Translate point to origin
        const x = point.x - origin.x;
        const y = point.y - origin.y;

        // Rotate point
        const rotatedX = x * cos - y * sin;
        const rotatedY = x * sin + y * cos;

        // Translate point back
        rotatedPoints.push({
            x: rotatedX + origin.x,
            y: rotatedY + origin.y
        });
    }

    return rotatedPoints;
}

